package main

import("bufio";"crypto/sha256";"encoding/hex";"encoding/json";"math";"os";"sort")
type Item struct{Name json.RawMessage `json:"name"`;Tag json.RawMessage `json:"tag"`;N int `json:"n"`;Tokens int `json:"tokens"`}
type Part struct{Kind string `json:"kind"`;Tokens int `json:"tokens"`;Items []Item `json:"items"`}
type Prompt struct{Tokens int `json:"tokens"`;Turns int `json:"turns"`;Counted bool `json:"counted"`;Parts []Part `json:"parts"`}
type Audit struct{Native []struct{Line int `json:"line"`} `json:"native_assistant_records"`;Matches []struct{NativeIndex int `json:"native_index"`;Matches []struct{Route int64 `json:"route_id"`} `json:"matches"`} `json:"native_usage_matches"`;Routing []struct{Line int `json:"line"`;Record struct{ID int64 `json:"id"`;Time string `json:"time"`;Model string `json:"model"`;Prompt Prompt `json:"prompt"`} `json:"record"`} `json:"routing_candidates"`}
func hash(s string)string{h:=sha256.Sum256([]byte(s));return hex.EncodeToString(h[:])}
func key(it Item)string{var name,tag any;json.Unmarshal(it.Name,&name);json.Unmarshal(it.Tag,&tag);b,_:=json.Marshal([]any{name,tag,it.N});return string(b)}
func identity(p Part)string{a:=[]string{};for _,it:=range p.Items{a=append(a,key(it))};sort.Strings(a);b,_:=json.Marshal(a);return hash(string(b))}
func interval(s,t int,et float64)(float64,float64){return (float64(s)-.5)/(float64(t)+et),(float64(s)+.5)/(float64(t)-et)}
func main(){raw,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};var a Audit;if json.Unmarshal(raw,&a)!=nil{panic("audit parse")};nativeUsers:=map[int]int{};f,e:=os.Open(os.Args[2]);if e!=nil{panic(e)};scan:=bufio.NewScanner(f);scan.Buffer(make([]byte,65536),100*1024*1024);n,users:=0,0;for scan.Scan(){n++;var m struct{Message struct{Role string `json:"role"`} `json:"message"`};if json.Unmarshal(scan.Bytes(),&m)!=nil{continue};if m.Message.Role=="user"{users++};if m.Message.Role=="assistant"{nativeUsers[n]=users}};f.Close();if scan.Err()!=nil{panic(scan.Err())};byID:=map[int64]int{};for j,r:=range a.Routing{byID[r.Record.ID]=j};rows:=[]any{};toolSigs:=map[string]int{};systemSigs:=map[string]int{};turnDiffs:=map[int]int{};ranges:=map[string][]float64{};commonLow,commonHigh:=0.0,math.Inf(1);itemIntervals:=map[string][]float64{};ratioMin,ratioMax:=math.Inf(1),math.Inf(-1);for _,m:=range a.Matches{if len(m.Matches)!=1{panic("not unique")};idx,ok:=byID[m.Matches[0].Route];if !ok{panic("missing route")};r:=a.Routing[idx];parts:=map[string]Part{};largest:="";maxT:=-1;for _,p:=range r.Record.Prompt.Parts{parts[p.Kind]=p;if p.Tokens>maxT{maxT=p.Tokens;largest=p.Kind}};sys,tools:=parts["system"],parts["tools"];if tools.Tokens==0{panic("missing tools")};toolSig,sysSig:=identity(tools),identity(sys);toolSigs[toolSig]++;systemSigs[sysSig]++;nativeLine:=a.Native[m.NativeIndex].Line;nativeUserN,found:=nativeUsers[nativeLine];if !found{panic("native assistant missing")};diff:=r.Record.Prompt.Turns-nativeUserN;turnDiffs[diff]++;et:=.5;if largest=="tools"{et=math.Max(.5,float64(len(parts)-1)*.5)};lo,hi:=interval(sys.Tokens,tools.Tokens,et);commonLow=math.Max(commonLow,lo);commonHigh=math.Min(commonHigh,hi);ratio:=float64(sys.Tokens)/float64(tools.Tokens);ratioMin=math.Min(ratioMin,ratio);ratioMax=math.Max(ratioMax,ratio);partMeta:=[]any{};ratios:=map[string]any{};representedTools:=0;for _,p:=range r.Record.Prompt.Parts{ns:=[]int{};for _,it:=range p.Items{ns=append(ns,it.N)};partMeta=append(partMeta,map[string]any{"kind":p.Kind,"tokens":p.Tokens,"items_count":len(p.Items),"item_n_sequence":ns,"displayed_identity_sha256":identity(p)});if p.Kind=="tools"{for _,it:=range p.Items{if it.N>0{representedTools+=it.N}else{representedTools++};l,h:=interval(it.Tokens,tools.Tokens,et);k:=key(it);old,ok:=itemIntervals[k];if !ok{old=[]float64{0,math.Inf(1)}};old[0]=math.Max(old[0],l);old[1]=math.Min(old[1],h);itemIntervals[k]=old}}};for _,kind:=range []string{"system","skills","memory","files","results","chat"}{p,present:=parts[kind];if !present{ratios[kind+"_tools"]=nil;continue};v:=float64(p.Tokens)/float64(tools.Tokens);ratios[kind+"_tools"]=v;rg,ok:=ranges[kind];if !ok{rg=[]float64{v,v}};rg[0]=math.Min(rg[0],v);rg[1]=math.Max(rg[1],v);ranges[kind]=rg};rows=append(rows,map[string]any{"native_index":m.NativeIndex,"native_assistant_line":nativeLine,"routing_line":r.Line,"route_id":r.Record.ID,"time_beijing":r.Record.Time,"model":r.Record.Model,"prompt_turns":r.Record.Prompt.Turns,"native_user_messages_so_far":nativeUserN,"turns_minus_native_users":diff,"prompt_tokens":r.Record.Prompt.Tokens,"prompt_counted":r.Record.Prompt.Counted,"ratios":ratios,"system_tools_ratio_interval_under_constant_precalibration_estimates":[]float64{lo,hi},"tools_rounding_error_bound":et,"largest_part":largest,"represented_tool_groups_count":representedTools,"tools_displayed_identity_sha256":toolSig,"system_displayed_identity_sha256":sysSig,"parts":partMeta})};itemFeasible:=0;for _,v:=range itemIntervals{if v[0]<=v[1]{itemFeasible++}};summary:=map[string]any{"calls":len(rows),"native_total_user_messages":users,"turns_minus_native_users_counts":turnDiffs,"tools_displayed_identity_signatures":toolSigs,"system_displayed_identity_signatures":systemSigs,"ratio_ranges":ranges,"system_tools_relative_span_percent":(ratioMax-ratioMin)/((ratioMax+ratioMin)/2)*100,"system_tools_common_feasible_ratio_interval":[]float64{commonLow,commonHigh},"constant_system_tools_estimate_ratio_feasible":commonLow<=commonHigh,"tools_item_ratio_intervals_feasible_count":itemFeasible,"tools_item_ratio_intervals_total":len(itemIntervals),"limits":[]string{"Name/tag/N signatures describe capped displayed aggregation identities, not raw tool schema/body hashes","calibrate scales all parts and items equally then rounds; largest part absorbs total rounding residual","Ratio intervals assume system not largest and tools error <=0.5 unless tools largest, when <=(part_count-1)/2","Absent skills/memory is absence of classification, not proof their text is absent from system","Native user counts use role=user records only; prompt.turns is parser heuristic, not wire input count","Constant estimated token ratios do not prove byte-for-byte stability or absence of equal-length mutations"}};out,e:=os.Create(os.Args[3]);if e!=nil{panic(e)};enc:=json.NewEncoder(out);enc.SetIndent("","  ");enc.Encode(map[string]any{"summary":summary,"calls":rows});out.Close();json.NewEncoder(os.Stdout).Encode(summary)}
